@@ -412,6 +412,34 @@ impl Autoscaler {
     fn evaluate_scale(&self, pool: &PoolState) -> ScaleDecision {
         // existing steady-state logic...
+        // burst budget fast-path: if demand > target and burst_capacity available, allow faster scale-up
+        if let Some(burst) = self.burst_accountant.peek(pool.id) {
+            if demand > pool.target_throughput && burst.available() > 0 {
+                return ScaleDecision::ImmediateAdd(self.calculate_burst_replicas(demand, &burst));
+            }
+        }
         ...
     }
+
+    // helper: calculate replicas allowed by burst budget
+    fn calculate_burst_replicas(&self, demand: u64, burst: &BurstAccountant) -> u32 {
+        // small helper math to map burst tokens -> replicas (approx)
+        ((demand as f64 / self.pool_capacity as f64).ceil() as u32).min(burst.max_replicas_allowed())
+    }
